  AvgDialog_118699_Content_2 = {
    Text = "Мир Кадат\nСейчас"
  },
  AvgDialog_118699_Content_20 = {
    Text = "Модели, которые Акгис может ткать, становятся все разнообразнее: спирали, ромбы, волны, цветы и животные."
  },
  AvgDialog_118699_Content_21 = {
    Text = "Большой {Male=Господин Хранитель,Female=Госпожа Хранительница}, что бы ты хотел......"
  },
  AvgDialog_118699_Content_22 = {
    Text = "Умная серенькая мышка проскользнула сквозь лазейку и верно положила сверкающее кольцо в лапку своего товарища."
  },
  AvgDialog_118699_Content_23 = {
    Text = "Хм, хорошо сделано, Коричневый."
  },
  AvgDialog_118699_Content_24 = {
    Text = "Мышонок смотрел на своего партнёра, который скучно зевнул, бросил кольцо в открытый ящик, в котором уже свалено множество беспорядочных «коллекционных» предметов."
