  AvgDialog_118702_Content_17 = {Text = "Но!"},
  AvgDialog_118702_Content_18 = {
    Text = "Страж, найди Дафодил! Мы не будем сдаваться —"
  },
  AvgDialog_118702_Content_19 = {
    Text = "Всё светлое исчезло. На далёком горизонте огромное неизвестное существо развернулось и постепенно исчезло в хаосе небытия."
