  AvgDialog_118951_Content_30 = {
    Text = "Я потратил немало сил, чтобы наточить лезвие до достаточной степени, чтобы резать дерево."
  },
  AvgDialog_118951_Content_31 = {
    Text = "Я вырезал много дней, стараясь Воссоздать детали, которые я представлял."
