  AvgDialog_118952_Content_29 = {
    Text = "Хотите выжить, хотите оставаться…"
  },
  AvgDialog_118952_Content_3 = {
    Text = "Зародыш бога рождается в сером теле."
  },
  AvgDialog_118952_Content_30 = {
    Text = "Тогда нужно убить это..."
  },
  AvgDialog_118952_Content_31 = {
    Text = "Слабый и наивный я..."
  },
  AvgDialog_118952_Content_4 = {
    Text = "Я очень устал от исчерпанной духовности, но лица всех полны безумной радости."
  },
  AvgDialog_118952_Content_5 = {
    Text = "<color=#F7F7F7>Второй день рождения богов</color>"
  },
  AvgDialog_118952_Content_6 = {
    Text = "Я окормляю святую утробу. Он засыпает с закрытыми глазами в пеленках."
