  AvgDialog_118959_Content_61 = {
    Text = "Пусть этот корабль перевернется."
  },
  AvgDialog_118959_Content_62 = {
    Text = "Черные занавеси, как шелк, изливающийся с небес, опускаются с безлукого черного солнца, затемняя и изолируя корпус корабля от внешнего мира."
  },
  AvgDialog_118959_Content_63 = {
    Text = "Безбрежная вода поднялась, погребая весь корабль Парадис в мрачной Бездне."
  },
  AvgDialog_118959_Content_64 = {
    Text = "Снова ты погружаешься в бескрайние тьмы."
