  AvgDialog_118960_Content_22 = {
    Text = "Тот, кто обладал властью до этого... должен быть..."
  },
  AvgDialog_118960_Content_23 = {
    Text = "Царь богов в этом мире уже родился... нет, лучше сказать, что он никогда не умирал."
  },
  AvgDialog_118960_Content_24 = {
