  AvgDialog_118960_Content_25 = {
    Text = "Он не хочет, чтобы ты погиб из-за жертвы, поэтому выделил немного силы, чтобы создать для тебя сон в сновидении."
  },
  AvgDialog_118960_Content_26 = {
