  AvgDialog_118960_Content_9 = {Text = "??!"},
  AvgDialog_118961_Content_1 = {
    Text = "Лжерождение"
  },
  AvgDialog_118961_Content_10 = {
    Text = "Удивлён? Единственный путь побега на этом корабле находится под моим контролем."
  },
  AvgDialog_118961_Content_11 = {
    Text = "Голиаф схватил Мёрфи, огромный лезвие у её горла.\nКровь стекает с её шеи, смешиваясь с неизлечимыми шрамами на груди."
