  AvgDialog_118961_Content_14 = {
    Text = "Извините, я всё ещё переживаю..."
  },
  AvgDialog_118961_Content_15 = {
    Text = "Это не Мириам не отпускает девочку, а эта девочка сдерживает Мириам."
