  AvgDialog_118961_Content_59 = {
    Text = "Ты имеешь в виду.."
  },
  AvgDialog_118961_Content_6 = {
    Text = "Мириам медлила с ответом, позади вас послышался глубокий насмешливый смех."
  },
  AvgDialog_118961_Content_60 = {
    Text = "Мириам помнила о том, что происходило при каждом цикле, она снова и снова ждала вас."
  },
  AvgDialog_118961_Content_61 = {
    Text = "Я могу соединиться с мечтой того парня, я был свидетелем конца этого мира. Думаю, и Милиам может тоже."
  },
  AvgDialog_118961_Content_62 = {
