  AvgDialog_120290_Content_61 = {
    Text = "<Change>Слишком... слишком красиво!! Какое лицо, такое прекрасное, такое... выдающееся... такое ужасное!!!"
  },
  AvgDialog_120290_Content_62 = {
    Text = "Господин Сюй! Господин Сюй... Пожалуйста, пожалуйста!!"
  },
  AvgDialog_120290_Content_63 = {
    Text = "Пожалуйста, посмотри на меня!"
