  AvgDialog_120291_Content_68 = {
    Text = "Все можно... Можно всё."
  },
  AvgDialog_120291_Content_69 = {
    Text = "Можно весь дом?"
  },
  AvgDialog_120291_Content_7 = {
    Text = "Ой, мисс, ты напугала меня до смерти. Бегать по дороге в истерике, ты хочешь погубить нас, простых людей."
