  AvgDialog_120296_Content_39 = {
    Text = "Никто не должен мешать нам побыть наедине, выходи! Убирайся!"
  },
  AvgDialog_120296_Content_4 = {
    Text = "Гэ Мэй И И хорошо выглядит, у нее хороший вкус, подаренные вещи имеют стиль. Ты тоже не можешь не мечтать, как она, чтобы веер был на лице."
  },
  AvgDialog_120296_Content_40 = {
    Text = "Женщина поспешила за тобой и, в Лечение на рев, быстро захлопнула Ворота."
  },
  AvgDialog_120296_Content_41 = {
    Text = "Я же говорил, не мешай господину, он может разозлиться, не бегай, моя маленькая тётя."
  },
  AvgDialog_120296_Content_42 = {
    Text = "Папа... Папа, что случилось? Почему он все время зовет мистера Сюй?"
