  AvgDialog_123120_Content_123 = {
    Text = "...ты прав."
  },
  AvgDialog_123120_Content_124 = {
    Text = "Ты убираешь измерительный прибор и поднимаешь руку, чтобы схватить Cеребряный ключ."
  },
  AvgDialog_123120_Content_125 = {
    Text = "Похоже, придётся рискнуть…"
  },
  AvgDialog_123120_Content_126 = {
    Text = "Бледный посланец, ты хочешь соединиться...?"
  },
  AvgDialog_123120_Content_127 = {
    Text = "Сальвадор нахмурил брови и недовольно смотрел на тебя. А ты просто молчал."
  },
  AvgDialog_123120_Content_128 = {
    Text = "Эй-эй, здесь ещё один «Гость из иного мира», можешь сказать что-то, что я понимаю?"
  },
  AvgDialog_123120_Content_129 = {
    Text = "Это означает, что %player%... соединяет ту неизвестную «Ворота», чтобы определить колебания измерений."
  },
  AvgDialog_123120_Content_13 = {
    Text = "Тот жрец на алтаре... это и есть Уайт."
  },
  AvgDialog_123120_Content_130 = {
    Text = "Что? Эта вещь очень странная, кто знает, к каким последствиям она приведет, не делай глупостей."
  },
  AvgDialog_123120_Content_131 = {
    Text = "Ты крепко держишь Cеребряный ключ и с тяжелым выражением лица направляешься к невидимым световым воротам. В этот момент действие важнее слов."
