  AvgDialog_126912_Content_6 = {
    Text = "Разве не опасно оставаться рядом с убийцей?"
  },
  AvgDialog_126912_Content_60 = {
    Text = "Звук Ванды исчез. Её благословение, произнесённое в последнем слове, также было поглощено тишиной."
  },
  AvgDialog_126912_Content_61 = {
