  AvgDialog_13734_Content_2 = {Text = "Тсс!!"},
  AvgDialog_13734_Content_3 = {
    Text = "Юухаши сидел на корточках на вершине высокого бархана, издавая раздражённое шипение — словно хищник, сосредоточенный на охоте, которого донимают назойливые мошки."
  },
  AvgDialog_13734_Content_4 = {
    Text = "Его губы были слегка приоткрыты, ноздри едва заметно подрагивали, а кроваво-красное сияние в глазах пылало ярче, чем когда-либо."
  },
  AvgDialog_13734_Content_5 = {
    Text = "<RedShake:Нашёл, нашёл…>"
