  AvgDialog_13735_Content_29 = {
    Text = "Потому что он сказал — на поле боя много людей."
  },
  AvgDialog_13735_Content_3 = {
    Text = "Хр-р-р… хр-р-р… пфф…"
  },
  AvgDialog_13735_Content_30 = {
    Text = "<Red:Много людей — значит, много крови.>"
