  AvgDialog_13736_Content_8 = {
    Text = "Проводник? Это… где мы…"
  },
  AvgDialog_13736_Content_80 = {Text = "Пфф."},
  AvgDialog_13736_Content_81 = {
    Text = "Насмотревшись на этот фарс, Юухаши потянулся и неспешно подошёл к тебе."
  },
  AvgDialog_13736_Content_82 = {
    Text = "Он обнял тебя за плечо, затем слегка повернул твой подбородок, пока твой взгляд не упёрся прямо в молчаливого мага."
  },
  AvgDialog_13736_Content_83 = {
