  AvgDialog_13736_Content_88 = {
    Text = "Второе — Граждане Лемвахи.\nА на первом месте…"
  },
  AvgDialog_13736_Content_89 = {
    Text = "Плечо пронзила резкая боль — Юухаши, громко хохоча, что есть силы хлопал тебя по плечу."
  },
  AvgDialog_13736_Content_9 = {
