  AvgDialog_15368_Content_49 = {
    Text = "Бесспорный… шедевр?"
  },
  AvgDialog_15368_Content_5 = {
    Text = "Не двигайся и не говори. Просто оставайся так.\nДа, вот именно так…"
  },
  AvgDialog_15368_Content_50 = {
    Text = "А ты что думаешь, Камилла?"
