  AvgDialog_18764_Content_26 = {
    Text = "Агриппа странно посмотрел на тебя."
  },
  AvgDialog_18764_Content_27 = {
    Text = "Конечно, нельзя."
  },
  AvgDialog_18764_Content_28 = {
    Text = "Хотите угадать, почему вы видите так много знакомых людей и мест в лабиринте?"
  },
  AvgDialog_18764_Content_29 = {
    Text = "Иллюзия? Нет, это память.."
  },
  AvgDialog_18764_Content_3 = {
    Text = "Ты наконец очистил последнюю «Шарлотт»."
  },
  AvgDialog_18764_Content_30 = {
    Text = "Агриппа покачал головой."
  },
  AvgDialog_18764_Content_31 = {
