  AvgDialog_18765_Content_22 = {
    Text = "Сказав это — Агриппа снова исчез."
  },
  AvgDialog_18765_Content_23 = {
    Text = "Не прошло и минуты, как перед вами появились одна, две... все больше Шарлотт."
  },
  AvgDialog_18765_Content_24 = {
    Text = "Угадай, какой из них Реальность я, хихи.."
  },
  AvgDialog_18765_Content_25 = {
    Text = "Ууу... Какая из Шарлотт является Агриппой?"
