  AvgDialog_18766_Content_12 = {Text = "<Big:!!!>"},
  AvgDialog_18766_Content_13 = {
    Text = "Это… что за место…?"
  },
  AvgDialog_18766_Content_14 = {
    Text = "Это место, где тебе придётся послушно сидеть всю оставшуюся жизнь."
  },
  AvgDialog_18766_Content_15 = {
    Text = "Девушка с улыбкой сидела на пустой столешнице, подперев подбородок руками, лениво покачивая закинутой правой ногой."
  },
  AvgDialog_18766_Content_16 = {
