  AvgDialog_18769_Content_23 = {
    Text = "Бордовые огненные волны устремляются в небо, смех, плач, крики... Разнообразные звуки собираются вместе, создавая симфонию ада."
  },
  AvgDialog_18769_Content_24 = {
    Text = "Скоро они найдут меня, @1 меня, а затем отрежут мою голову, как и моих родителей."
