  AvgDialog_18891_Content_12 = {
    Text = "Что за сумасшедший?"
  },
  AvgDialog_18891_Content_13 = {
    Text = "Вау! Как ты вдруг появился! И кстати, я же сказал, чтобы ты пришёл сам!"
  },
  AvgDialog_18891_Content_14 = {
    Text = "Маленькая мышка прыгнула на плечо ребенка с капюшоном и напряженно напрягла усы, глядя на тебя."
