  AvgDialog_18891_Content_21 = {
    Text = "Ах! Мой кошелёк!"
  },
  AvgDialog_18891_Content_22 = {
    Text = "Оргр торопливо протянул руку к кошельку, Дженкинс уклонился в сторону, и кошелёк снова исчез как по волшебству."
  },
  AvgDialog_18891_Content_23 = {
    Text = "Слишком невежливо, маленький золотистый ретривер.\nВсе ли люди из Университета Мисаг так обижают маленькую девочку, оставшуюся на улице?"
