  AvgDialog_18891_Content_44 = {Text = "Пи!"},
  AvgDialog_18891_Content_45 = {
    Text = "Маленькая мышка по имени Браун чирикала \"чирик-чирик\", держа кошелёк в зубах, прыгнула с большого дерева и бросила его в объятия Оргра."
  },
  AvgDialog_18891_Content_46 = {
    Text = "Я отведу вас к сумасшедшим больным, и расскажу всё, что знаю, в обмен —"
