  AvgDialog_18909_Content_35 = {
    Text = "Лондиниум общая информация №3 ——"
  },
  AvgDialog_18909_Content_36 = {
    Text = "«В Восточном районе цена человека неизмерима. Потому что они ничего не стоят.»"
  },
  AvgDialog_18909_Content_37 = {
    Text = "В тихом коридоре медленно открывается Ворота с металлической табличкой.\nИз щели выскользнула мышь, она посмотрела влево и вправо, затем чирикнула чирик в сторону тени коридора."
