  AvgDialog_18909_Content_38 = {Text = "Пи!"},
  AvgDialog_18909_Content_39 = {
    Text = "В прошлый раз ты тоже сказал, что никого нет! Если бы я не встретил Ай Джис, я бы сильно пострадал."
  },
  AvgDialog_18909_Content_4 = {
    Text = "Увидев, что никто не поддержал разговор, она нахмурилась и легонько похлопала девочку по спине.\nДевочка, кажется, задумалась, а тут вздрогнула от неожиданности и поспешно поклонилась вам."
  },
  AvgDialog_18909_Content_40 = {
    Text = "Дженкинс высунул голову из-за угла, подтвердил, что в коридоре никого нет, затем выскользнул через щель, повернулся и закрыл Ворота."
  },
  AvgDialog_18909_Content_41 = {
    Text = "Писк чирик, пии-пи-пи!"
