  },
  AvgDialog_18909_Content_49 = {
    Text = "О... Это... Бухгалтерская книга?\nМайкл, Мальчик, 5 лет, 10 лео мастерская; Диана, девушка, 23 года, 5 лео мастерская.."
  },
  AvgDialog_18909_Content_5 = {
