  AvgDialog_18911_Content_24 = {
    Text = "Сообщение о своих проблемах — это один из методов психологической терапии, а я как раз являюсь слушателем с профессиональной подготовкой."
  },
  AvgDialog_18911_Content_25 = {
    Text = "Взгляд, изучающий лица толпы, поочередно скользил по каждому и, наконец, остановился на тебе."
