  AvgDialog_18915_Content_35 = {
    Text = "Ты действительно рыцарь?"
  },
  AvgDialog_18915_Content_36 = {
    Text = "Оргр похлопал себя по груди, нарукавник стукнул его по груди, что на мгновение исказило его эмоцию."
  },
  AvgDialog_18915_Content_37 = {
    Text = "Как подлинная клятва! Сама королевская семья наградила меня, с тех пор я живу для защиты."
  },
  AvgDialog_18915_Content_38 = {
    Text = "Как я тебе завидую, такой храбрый... Чтобы встать на защиту человека, которого только что узнал."
  },
  AvgDialog_18915_Content_39 = {
    Text = "Жаль, но я не рыцарь, не принцесса, даже не обычное Люди, а всего лишь жалкий.."
  },
  AvgDialog_18915_Content_4 = {
    Text = "Добрый день, госпожа Сара."
  },
  AvgDialog_18915_Content_40 = {
    Text = "Её последний звук Быть Сожранным."
  },
  AvgDialog_18915_Content_41 = {
    Text = "Оргр, ты сказал, что рыцарь будет защищать всех людей.."
  },
  AvgDialog_18915_Content_42 = {
    Text = "А что с преступниками? Даже... убийцами?"
