  AvgDialog_18930_Content_2 = {
    Text = "...Я не понимаю, о чём ты говоришь."
  },
  AvgDialog_18930_Content_3 = {
    Text = "Не волнуйся... Я просто любопытен, не буду раскрывать..."
  },
  AvgDialog_18930_Content_4 = {
