  AvgDialog_18940_Content_49 = {
    Text = "Слушаюсь!"
  },
  AvgDialog_18940_Content_5 = {
    Text = "Великий... она всего лишь обычная девочка из трущоб, она не представляет для вас никакой угрозы."
  },
  AvgDialog_18940_Content_50 = {
    Text = "Не... я не ухожу, вы еще не согласились.."
  },
  AvgDialog_18940_Content_51 = {
    Text = "<Big:Меньше слов, пошли!>"
  },
  AvgDialog_18940_Content_52 = {
    Text = "Сопротивление 24 не имело никакого эффекта, её тащили, как тряпку."
