  AvgDialog_18941_Content_60 = {
    Text = "Болезненная, пылающая, недостижимая любовь!"
  },
  AvgDialog_18941_Content_61 = {
    Text = "На её холодном алтаре я готов принести в жертву свои слёзы, свои вздохи и свою самую чистую.."
  },
  AvgDialog_18941_Content_62 = {Text = "Душа!"},
  AvgDialog_18941_Content_64 = {
    Text = "Почему это стало пробуждающее тело?"
  },
  AvgDialog_18941_Content_65 = {
