  AvgDialog_18941_Content_77 = {
    Text = "Бум! Бум ——!"
  },
  AvgDialog_18941_Content_78 = {
    Text = "Запрос ещё не достиг конца, когда из глубин неприметного погреба внезапно послышались глухие удары."
  },
  AvgDialog_18941_Content_79 = {
    Text = "Вы затаили дыхание, и вам показалось, что вы слышите низкие и подавленные, прерывистые звуки плача детей."
  },
  AvgDialog_18941_Content_8 = {
    Text = "@2-й год зимой\nЛентиниен"
