  AvgDialog_18941_Content_80 = {
    Text = "Голод.."
  },
  AvgDialog_18941_Content_81 = {
    Text = "<Change>голод... голод голод голод голод голод голод голод голод"
  },
  AvgDialog_18941_Content_9 = {
    Text = "Это было шесть лет назад, в зимнюю ночь, когда мне посчастливилось увидеть первый снег в Лентиниене и молодую девушку, лежащую на снегу."
  },
  AvgDialog_18942_Content_1 = {
    Text = "Старший товарищ, вы звучите очень слабость, вы пострадали?"
  },
  AvgDialog_18942_Content_2 = {
    Text = "Мы потеряли связь с девушкой Дора, а у вас?"
  },
  AvgDialog_18942_Content_3 = {
    Text = "Эй, ты когда-нибудь видел девушку, которая больше меня?"
  },
  AvgDialog_18942_Content_4 = {
    Text = "Кашель... кашель... кашель... по очереди спрашивать."
  },
  AvgDialog_18943_Content_1 = {
    Text = "Бледная и худая Молодая женщина опирается на стену. Она полуприкрыла глаза, её лицо покраснело, дыхание очень частое."
  },
  AvgDialog_18943_Content_10 = {
    Text = "Острая боль, как от укола иглой, жестоко пронзила шею, продолжая углубляться, всё глубже и глубже.."
  },
  AvgDialog_18943_Content_11 = {Text = "<Big:?!>"},
  AvgDialog_18943_Content_12 = {
    Text = "В ушах раздаётся Алчность сосания и глотания. Что-то мягкое и холодное крепко прилипло к шее."
  },
  AvgDialog_18943_Content_13 = {
    Text = "Ух... Уходи, уходи...!!"
  },
  AvgDialog_18943_Content_14 = {
    Text = "Дай мне, дай мне.."
  },
  AvgDialog_18943_Content_15 = {
    Text = "Чувство быстрой потери крови не из приятных. У вас темнеет в глазах, сердце начинает биться с ускорением."
  },
  AvgDialog_18943_Content_17 = {
    Text = "Я зову тебя…<Big:убирайся!!!>"
  },
  AvgDialog_18943_Content_2 = {
    Text = "Кажется, она пострадала, давайте я проверю."
  },
  AvgDialog_18943_Content_3 = {
