  AvgDialog_18944_Content_14 = {
    Text = "21:55, Музей восковых фигур Роджерса\nВестибюль"
  },
  AvgDialog_18944_Content_15 = {
    Text = "Внутри здания расставлены старые предметы обстановки, при каждом вдохе чувствуется сухая пыль, а едва уловимый зловонный запах пропитывает воздух."
  },
  AvgDialog_18944_Content_16 = {
    Text = "За стойкой сидит девушка, с увлечением листающая журнал под названием «Руководство по содержанию животных»."
  },
  AvgDialog_18944_Content_17 = {
    Text = "Добрый вечер, мадам. Скажите, пожалуйста, это музей восковых фигур Роджерса?"
  },
  AvgDialog_18944_Content_19 = {
    Text = "Можно нам войти и осмотреться?"
  },
  AvgDialog_18944_Content_2 = {
    Text = "Динь линь~"
  },
  AvgDialog_18944_Content_21 = {
    Text = "Хм-хм, лалала~"
  },
  AvgDialog_18944_Content_22 = {
    Text = "Жаль, кажется, у этой дамы есть проблемы со слухом, давайте зайдем."
  },
  AvgDialog_18944_Content_23 = {
    Text = "Ненавижу, с самого начала так грубо. Если ты хочешь привлечь моё внимание..."
  },
  AvgDialog_18944_Content_24 = {
    Text = "Ты преуспела, моя сладкая~"
