  AvgDialog_18944_Content_26 = {
    Text = "Пфф. сладкая моя...?"
  },
  AvgDialog_18944_Content_27 = {
    Text = "Впервые встречаемся, я администратор музея восковых фигур Роджерса, можно просто называть меня Пандия~"
  },
  AvgDialog_18944_Content_28 = {
    Text = "Ваш визит глубокой ночью — это чтобы восхищаться искусством, очистить душу, или вы пришли, как некоторые самоуверенные студенты-медики, чтобы Кража материалы?"
  },
  AvgDialog_18944_Content_29 = {
    Text = "...студент-медик? ворует материалы?"
  },
  AvgDialog_18944_Content_3 = {
    Text = "Когда вы открыли Ворота, сильное ошеломление накатывает на вас."
  },
  AvgDialog_18944_Content_30 = {
    Text = "Ой! Неужели... вы пришли ко мне @2?"
