  AvgDialog_18944_Content_61 = {
    Text = "Хихи, секрет~"
  },
  AvgDialog_18944_Content_62 = {
    Text = "Черт, что это такое."
  },
  AvgDialog_18944_Content_63 = {
    Text = "<SmallShake:Если я захочу потихоньку сделать что-то плохое, ты всё равно не обнаружишь…>"
  },
  AvgDialog_18944_Content_64 = {
    Text = "Ой, непослушные мышки действительно вызывают смешанные чувства.\nДам вам одну точку Подсказка."
