  AvgDialog_18955_Content_24 = {
    Text = "Роджерс не отвечает. Точнее говоря, он давно потерял способность отвечать."
  },
  AvgDialog_18955_Content_25 = {
    Text = "<Small:Если мы не уйдем сейчас, мы все умрем здесь…>"
  },
  AvgDialog_18955_Content_27 = {
