  AvgDialog_18955_Content_36 = {
    Text = "<Red:Пандия, что ты делаешь... моя рука...>"
  },
  AvgDialog_18955_Content_37 = {
    Text = "Я покину с лордом Роджерсом. Рея, помоги мне задержать их!"
  },
  AvgDialog_18955_Content_38 = {Text = "...что?"},
  AvgDialog_18955_Content_4 = {
    Text = "В длинных, одиноких лучах света Мальчик медленно и одиноко бредёт."
  },
  AvgDialog_18955_Content_5 = {
    Text = "Он прошёл через коридор, следуя призыву, Шаг за шагом подошёл к мужчине."
  },
  AvgDialog_18955_Content_6 = {
    Text = "Мужчина погружён в багровый восковой бассейн, слёзы стекают по извилистым руслам на его лице."
  },
  AvgDialog_18955_Content_7 = {
    Text = "Господин Восковая Фигура, вы это, что вы делаете?!"
  },
  AvgDialog_18955_Content_8 = {
    Text = "Это изувеченное тело смогло продержаться до сих пор, это действительно чудо.."
  },
  AvgDialog_18955_Content_9 = {
    Text = "Смерть в воске — самое совершенное пристанище, которое я могу представить."
