  AvgDialog_18956_Content_3 = {Text = "Не——"},
  AvgDialog_18956_Content_4 = {
    Text = "Ты снова оказываешься полностью обёрнутым в белый восковый слой."
  },
  AvgDialog_18956_Content_5 = {
    Text = "Они жадно высасывали кровь, словно никогда не смогут насытиться, до тех пор пока не почувствовали в ней странного вкуса."
  },
  AvgDialog_18956_Content_6 = {
