  AvgDialog_18982_Content_46 = {
    Text = "Все маятники в зале Начало активно откликаться, разнообразные звуки колоколов слились в море звуковых волн."
  },
  AvgDialog_18982_Content_47 = {
    Text = "Когда запреты полностью нарушены, правила подвергаются таптанью, колокол суда больше не может хранить молчание и издаёт самые резкие угрозы."
  },
  AvgDialog_18982_Content_48 = {
    Text = "Гром——!"
  },
  AvgDialog_18982_Content_49 = {
    Text = "Внезапно под ногами раздался резкий жужжащий звук, сопровождаемый плачем ребёнка, который разносился вокруг музея восковых фигур."
  },
  AvgDialog_18982_Content_5 = {
