  AvgDialog_18982_Content_50 = {
    Text = "Бум—— !!"
  },
  AvgDialog_18982_Content_51 = {
    Text = "Под тобой словно разверзся огромный Мальстрём, всё пожирающий с неутолимым голодом."
  },
  AvgDialog_18982_Content_52 = {
    Text = "Ааааа——"
  },
  AvgDialog_18982_Content_6 = {
    Text = "Сестра.."
  },
  AvgDialog_18982_Content_7 = {
