  AvgDialog_18983_Content_14 = {
    Text = "Кхе-кхе…"
  },
  AvgDialog_18983_Content_15 = {
    Text = "Отлично, старший товарищ Уильям! Я уж думал.."
  },
  AvgDialog_18983_Content_16 = {
