  AvgDialog_18983_Content_17 = {
    Text = "Отвлекаться — плохая привычка, следователь."
  },
  AvgDialog_18983_Content_18 = {
    Text = "Не ожидал, что <Blue:та дама> также имеет связи с Союзом скульпторов, это моя недосмотр."
  },
  AvgDialog_18983_Content_19 = {
    Text = "Кстати, вы не видели маленькую восковую фигуру? С золотистыми кудрями, в черном вечернем Наряд.."
  },
