  AvgDialog_18997_Content_20 = {
    Text = "{Male=Он,Female=Она} уже ушёл(a)."
  },
  AvgDialog_18997_Content_21 = {
    Text = "Ротань сидела в самом дальнем углу Чёрного бассейна, подняв голову и глядя на пустое небо.\nИменно там некогда появилась Тави."
