  AvgDialog_19009_Content_22 = {
    Text = "Эх, скупой."
  },
  AvgDialog_19009_Content_23 = {
    Text = "Ротань повернулась и вышла из комнаты, взгляд Лили тревожно следовал за её спиной."
  },
  AvgDialog_19009_Content_24 = {
    Text = "Страшная сестра ушла. Мы можем немного расслабиться, Правда, Лили?"
  },
  AvgDialog_19009_Content_25 = {
    Text = "Малышка Мерцание, действительно расслабилась, или вообще непонятно ситуацию сейчас."
  },
  AvgDialog_19009_Content_26 = {
    Text = "Ты знаешь, где Лиза, не так ли?"
