  AvgDialog_19019_Content_67 = {
    Text = "Кто вы такие?"
  },
  AvgDialog_19019_Content_68 = {
    Text = "Я зовусь Хэнком, он — Джон, мы все друзья Лизы!"
  },
  AvgDialog_19019_Content_69 = {
    Text = "Тот день Лили увела Лизу в пригород, мы видели это собственными глазами!"
  },
  AvgDialog_19019_Content_7 = {
    Text = "Мы как ни зовём тебя, не можем разбудить, а этот ребёнок сказал, что хочет посмотреть, в чём дело... Не думали, что он так и заснёт, прижавшись к твоей груди."
  },
  AvgDialog_19019_Content_70 = {
    Text = "Хватит болтать, {Male=он,Female=она} точно связаны с этим дьяволом, покажи им, кто тут главный!"
  },
  AvgDialog_19019_Content_71 = {
    Text = "Защити маму Лизы!"
  },
  AvgDialog_19019_Content_72 = {
    Text = "...Ты не думаешь, что мы всё время придираемся к детям?"
  },
  AvgDialog_19019_Content_8 = {
    Text = "Малышка с неохотой поднялась, её взгляд не отрывался от твоей груди, полный нежной привязанности.\nТы опустил голову и увидел Cеребряный ключ, который продолжал сверкать, даже во сне, не снимаясь."
