  AvgDialog_19078_Content_15 = {
    Text = "……………"
  },
  AvgDialog_19078_Content_16 = {
    Text = "Коридор крайне тесный, вы вынуждены идти, согнувшись.\nСвет не проникает сюда, видно лишь кромешную тьму, где не видно даже протянутой руки."
  },
  AvgDialog_19078_Content_17 = {
    Text = "Правда... можно покинуть это место?"
