  AvgDialog_19115_Content_19 = {
    Text = "Вау——спасите——"
  },
  AvgDialog_19115_Content_2 = {
    Text = "Эти тела, похожие на человеческие, но с характеристиками водных организмов, издали странные протяжные и жуткие стоны.\nЗвук был хаотичным и пронзительным, но вы почему-то поняли их значение."
  },
  AvgDialog_19115_Content_20 = {
    Text = "Эти парни догоняют! Пришёл!"
  },
  AvgDialog_19115_Content_21 = {
    Text = "Осторожно!"
  },
  AvgDialog_19115_Content_22 = {
    Text = "Девушка, тяжело дыша, подбежала к тебе, а следом за ней пересечь палубу, безусловно, ещё больше врагов."
  },
  AvgDialog_19115_Content_3 = {
    Text = "Они говорят… «Верните нам»?"
