  AvgDialog_19984_Content_69 = {
    Text = "Ой, даже это обнаружили?"
  },
  AvgDialog_19984_Content_7 = {
    Text = "Большая собака по кличке «Кум» сидела на земле и послушно облизала лапу."
  },
  AvgDialog_19984_Content_70 = {
    Text = "Хотя я не могу полностью разобрать все детали происхождения того адского пса, но я всё же кое-что знаю."
