  AvgDialog_20475_Content_1 = {
    Text = "Наконец... я тебя вижу."
  },
  AvgDialog_20475_Content_10 = {
    Text = "Снежная гора уже начала поглощать вас... необходимо как можно быстрее победить монстра и уничтожить ядро!"
