  AvgDialog_21805_Content_25 = {
    Text = "Память Ореты — это загадка. Растворение поглотило её прошлое до пробуждения, и из её детских слов трудно найти достаточно деталей, чтобы сложить полную картину."
  },
  AvgDialog_21805_Content_26 = {
