  AvgDialog_22120_Content_57 = {
    Text = "Клик ——"
  },
  AvgDialog_22120_Content_58 = {
    Text = "Услышав звук открывшейся двери в гостиной, Мужчина не обернулся, продолжал с интересом глядя в окно."
  },
  AvgDialog_22120_Content_59 = {
    Text = "Какой прекрасный сад, леди Колетт."
