  AvgDialog_22120_Content_78 = {
    Text = "Она старалась сохранять благородную улыбку, но бокал с красным вином в её руке дрожал непроизвольно."
  },
  AvgDialog_22120_Content_79 = {
    Text = "Лицо дамы высшего общества отразилось в колеблющемся бокале, словно язва гниения."
  },
  AvgDialog_22120_Content_8 = {
    Text = "Я ведь уже говорил тебе Лечение."
  },
  AvgDialog_22120_Content_80 = {
    Text = "Все мы станем победителями, господин Герберт."
  },
  AvgDialog_22120_Content_9 = {
    Text = "В новом Западном берегу всё прекрасное должно быть увидено."
