  AvgDialog_22121_Content_2 = {
    Text = "Мы приехали!"
  },
  AvgDialog_22121_Content_20 = {
    Text = "После того как мы приехали сюда, мы часто играем в эту игру, иногда я играю аристократом, а иногда Колетт."
  },
  AvgDialog_22121_Content_21 = {
    Text = "Эту картину нарисовала она, но получилась не очень красиво. Однако в тот момент у нас не было больше мела."
