  AvgDialog_22121_Content_59 = {
    Text = "Хотя она потом заперла тебя в теплице и подожгла её, кажется, ты не испытываешь к ней ненависти."
  },
  AvgDialog_22121_Content_6 = {
    Text = "У подножия, в огромном саду, росла блеклая серая трава. Вы направляетесь в сад."
