  AvgDialog_22121_Content_65 = {
    Text = "Не волнуйтесь, не сдерживайте свои эмоции."
  },
  AvgDialog_22121_Content_66 = {
    Text = "Давай продолжим искать сборник стихов."
  },
  AvgDialog_22121_Content_67 = {
