  AvgDialog_22121_Content_73 = {
    Text = "Странно... это место, тут яма.."
  },
  AvgDialog_22121_Content_74 = {
    Text = "Сборник стихов... сборник стихов должен был быть похоронен здесь!!"
  },
  AvgDialog_22121_Content_75 = {
    Text = "Оно много лет назад там уже не было."
