  AvgDialog_22121_Content_76 = {Text = "!!!"},
  AvgDialog_22121_Content_77 = {
    Text = "Кто?! ——"
  },
  AvgDialog_22121_Content_78 = {
    Text = "Знакомый звук раздался. Вы быстро обернулись."
  },
  AvgDialog_22121_Content_79 = {
    Text = "Дверь задней части виллы открылась, и на пороге стояла та дама высшего общества, которую вы встретили на пароходе, с высоты своего положения взирая на вас."
