  AvgDialog_23351_Content_2 = {
    Text = "Вот и вернулся, мой рыцарь."
  },
  AvgDialog_23351_Content_20 = {
    Text = "Тогда выпьем одну чашку."
  },
  AvgDialog_23351_Content_3 = {
    Text = "Солер улыбается и сидит в углу, по-прежнему сияющая."
