  AvgDialog_23352_Content_9 = {
    Text = "Странно, на этой картине одна точка пыли, как будто кто-то регулярно за ней ухаживает."
  },
  AvgDialog_23353_Content_1 = {Text = "Яйцо"},
  AvgDialog_23353_Content_10 = {
    Text = "Рамона нахмурилась, в её глазах читалось Беспокойство."
