  AvgDialog_23859_Content_44 = {
    Text = "<Big:у————>"
  },
  AvgDialog_23859_Content_45 = {
    Text = "Как будто жаворонок откликается на колоратурную арию оперной певицы, обычно длинный гудок паровоза отзывается на молитву Рамоны."
  },
  AvgDialog_23859_Content_48 = {
    Text = "Я знаю, что ты хочешь сказать, но, пожалуйста, Не сейчас."
  },
  AvgDialog_23859_Content_49 = {
    Text = "Мы не можем отправиться в море на борту Сонанил, у этого корабля слишком много странностей."
  },
  AvgDialog_23859_Content_5 = {
    Text = "Ты и Рамона идёте по шаткому трапу на борт, дорога вверх окутана туманом, из-за чего её Конец невозможно разглядеть."
  },
  AvgDialog_23859_Content_50 = {
    Text = "Пойди посмотри на другом конце палубы! Я вижу там тросы, которые крепят спасательные лодки. Попробуем эвакуироваться через море."
  },
  AvgDialog_23859_Content_51 = {
    Text = "Подождите... кажется, слышится какой-то звук."
  },
  AvgDialog_23859_Content_53 = {
    Text = "Лица, похожие на рыбьи, появились на палубе, и те, кто загнал вас на корабль, продолжают наступать."
