  AvgDialog_23884_Content_13 = {
    Text = "Я всего лишь инструмент для переговоров, назначенный сверху. Если она совсем умрёт, разве переговоры не пойдут насмарку?"
  },
  AvgDialog_23884_Content_130 = {
    Text = "Так что вы не желали слишком долго задерживаться в мистическом мире, это и дало нам шанс на Побег."
  },
  AvgDialog_23884_Content_131 = {
