  AvgDialog_35988_Content_78 = {
    Text = "Змеи... везде змеи!"
  },
  AvgDialog_35988_Content_79 = {
    Text = "Потолок, пол, стены… Вокруг неизвестно когда заползли змеи, словно бесчисленные бледные водоросли, плывущие в тихой черной реке."
