  AvgDialog_43775_Content_32 = {
    Text = "Не говори ерунды, у меня всё в порядке ——"
  },
  AvgDialog_43775_Content_33 = {
    Text = "Не нужно отнекиваться, девушка, наши запасы воды мы только что допили, а ты с вчерашнего дня даже не прикасалась к своему водяному мешку, верно?"
  },
  AvgDialog_43775_Content_34 = {
    Text = "Что там внутри?"
