  AvgDialog_43775_Content_35 = {Text = "!"},
  AvgDialog_43775_Content_36 = {
    Text = "Ты резко вырываешь флягу у Рамоны, она тяжёлая, неясная чёрная Чёрная Чёрная тень внутри колышется."
  },
  AvgDialog_43775_Content_37 = {
    Text = "Лекк поднял Конец водного мешка, и густая черная жидкость полилась чернильной тьмой."
  },
  AvgDialog_43775_Content_38 = {
    Text = "Это Р-слизь."
  },
  AvgDialog_43775_Content_39 = {
    Text = "Рамона, твой мешок с водой... это когда?"
  },
  AvgDialog_43775_Content_4 = {
    Text = "Перед отправлением, никто не сказал мне, что здесь, помимо так называемой <Yellow:«Материнское древо урожая»>, будут ещё и эти —"
  },
  AvgDialog_43775_Content_40 = {
    Text = "Примерно два дня назад.\nЯ внимательно наблюдал, и, похоже, только вода в моей фляге оказалась с этой проблемой."
