  AvgDialog_43777_Content_9 = {
    Text = "Узор дерева глубокое Вдаль от берегов в крышку материала непонятно, крона пышная, корни переплетены, мрачный оттенок отражает тусклый и загадочный Погоня за светом."
  },
  AvgDialog_43788_Content_1 = {
    Text = "Кстати, Лекк, подойди сюда."
  },
  AvgDialog_43788_Content_10 = {
    Text = "Эх, Юй Ли действительно имеет некоторые особые методы."
  },
  AvgDialog_43788_Content_100 = {
    Text = "Оказывается, так и есть!\nЗначит, ты путешественник, посетивший Ремуахе!"
  },
  AvgDialog_43788_Content_101 = {
    Text = "Ремуахе давно не было новых гостей!\nЯ сразу же попрошу всех подготовить самую веселую костровую вечеринку, ты обязательно должен хорошо провести время!"
  },
  AvgDialog_43788_Content_102 = {Text = "Ужин?"},
  AvgDialog_43788_Content_103 = {
    Text = "Да! Хотя у арамеев и недостаточно внешних знаний, их внутренний мир остаётся открытым."
  },
  AvgDialog_43788_Content_104 = {
    Text = "Как только ты переживешь Роскошный Роскошный пир, ты станешь членом племени Арамиты!"
