  AvgDialog_43788_Content_105 = {
    Text = "Как один из своих, ты можешь избежать наказания, если пообещаешь не рассказывать о том, что видел и слышал в лагере."
  },
  AvgDialog_43788_Content_106 = {
    Text = "Почувствуйте гостеприимство арамеев на пиру!"
  },
  AvgDialog_43788_Content_11 = {
    Text = "Как только вы прибыли в лагерь, группа жителей в аранской одежде окружила верблюдов Юлиетт со всех сторон."
  },
  AvgDialog_43788_Content_12 = {
    Text = "Юлиетт девушка пришла, быстро подайте приготовленные дары!"
