  AvgDialog_43809_Content_15 = {
    Text = "Извините, он немного перестарался."
  },
  AvgDialog_43809_Content_16 = {
    Text = "Как ты и догадался, он самый быстро растущий среди этих детей."
  },
  AvgDialog_43809_Content_17 = {
    Text = "В противоположность этому.."
  },
  AvgDialog_43809_Content_18 = {
    Text = "Юлиетт привела вас к скромной колыбели."
  },
  AvgDialog_43809_Content_19 = {
    Text = "Посмотрите на этого ребёнка."
  },
  AvgDialog_43809_Content_2 = {
    Text = "02:00 ночи шатер посланников"
  },
  AvgDialog_43809_Content_20 = {
    Text = "Это был Дитя, ещё находящийся в колыбели, по всему его телу расползались древовидные тёмные линии."
  },
  AvgDialog_43809_Content_21 = {
    Text = "Поверхность не показывает уродства, на самом деле уже заражена болезнью материнского дерева."
  },
  AvgDialog_43809_Content_22 = {
    Text = "Попробуй положить руку ему на кожу."
  },
  AvgDialog_43809_Content_23 = {
    Text = "Вы коснулись поверхности тела ребёнка. Это не было тем мягкой и нежной кожей младенца, как вы ожидали, а скорее напоминало грубую и растрескавшуюся кору старого дерева."
  },
  AvgDialog_43809_Content_3 = {
    Text = "В шатре посланника полно постелей, несколько детей пяти-шести лет свернулись калачиком и спят сладким сном.\nК вам направляется юноша с благородным и решительным обликом."
  },
  AvgDialog_43809_Content_4 = {
    Text = "Госпожа Юлиетт, вы вернулись."
  },
  AvgDialog_43809_Content_5 = {
    Text = "Неферуре, мой послушный ребенок.\nВсе уже отдыхают?"
