  AvgDialog_44436_Content_1 = {
    Text = "Почему... почему.."
  },
  AvgDialog_44436_Content_10 = {
    Text = "Счастливый просто жизнью — это «24»."
  },
  AvgDialog_44436_Content_11 = {
    Text = "Мучимый Союзом скульпторов, также «24»."
  },
  AvgDialog_44436_Content_12 = {
    Text = "Не... Если бы не твоя трусость, тебя бы не застал тот Доктор.."
  },
  AvgDialog_44436_Content_13 = {
    Text = "Тише…"
  },
  AvgDialog_44436_Content_14 = {
    Text = "Мейсон легонько прикрыл рот Тени.Она наклонила голову и прильнула к уху Тени."
  },
  AvgDialog_44436_Content_15 = {
