  AvgDialog_45442_Content_34 = {
    Text = "Я буду исполнять обязанности главы клана и охранять гроб Тайис."
  },
  AvgDialog_45442_Content_35 = {
    Text = "Каждый будущий шаг аланов будет передвигаться вперёд под пристальным взглядом <Red:Тайис>."
  },
  AvgDialog_45442_Content_36 = {
    Text = "Каждый шаг аланов в будущем будет передвигаться вперёд под наблюдением <Red:Её Величество>."
  },
  AvgDialog_45442_Content_37 = {
    Text = "Каждый шаг аланов в будущем будет передвигаться вперёд под наблюдением <Red:@1Ваша милость>."
