  AvgDialog_47168_Content_47 = {
    Text = "Я согласен, отец. Ты чересчур снисходителен ко мне."
  },
  AvgDialog_47168_Content_48 = {
    Text = "Вот результат моей смешной алхимии, любуйтесь, отец!"
  },
  AvgDialog_47168_Content_49 = {
    Text = "Солдат почувствовал опасность и резко бросился к двоим."
  },
  AvgDialog_47168_Content_5 = {
