  AvgDialog_47168_Content_6 = {
    Text = "Эх... ладно, может быть, ты и не поймёшь эти вещи."
  },
  AvgDialog_47168_Content_60 = {
    Text = "Это мой Подарок для тебя, старина, тебе нравится?"
