  AvgDialog_47168_Content_65 = {
    Text = "Пффф——"
  },
  AvgDialog_47168_Content_66 = {
    Text = "Острый нож вошел в иссохшую грудь старика. Последнее, что он увидел, была радостная улыбка на лице ублюдка."
  },
  AvgDialog_47168_Content_68 = {
