  AvgDialog_47168_Content_95 = {
    Text = "Вы ранее упомянули те «серебристое вещество».."
  },
  AvgDialog_47168_Content_96 = {
    Text = "Да, верно, это те серебряные вещества... золото? драгоценные камни? хаха, это всё мусор!"
  },
  AvgDialog_47168_Content_97 = {
    Text = "Что такое серебряное вещество, что такое алхимия? Это Огромная Огромная сила! Перед силой что значат богатства? Они всего лишь бонус, который прилагается к силе."
  },
  AvgDialog_47168_Content_98 = {
    Text = "Алхимия — это Огромная Огромная сила... Мириам, ты и есть Огромная Огромная сила! Давай, чокнемся!"
  },
  AvgDialog_47168_Content_99 = {
    Text = "Хочешь воскрешение человека, нужно только те серебристые вещества?"
  },
  AvgDialog_47169_Content_1 = {
    Text = "Старый Близкий Близкий друг"
  },
  AvgDialog_47169_Content_10 = {
    Text = "Талис воскресил меня, он наверняка что-то знает. Я найду способ вашего воскрешения у него!"
  },
  AvgDialog_47169_Content_100 = {
    Text = "Он заплатит за своё колебание."
