  AvgDialog_47169_Content_14 = {
    Text = "Тень не произнесла ни слова. Свет и щупальца закрывали его лицо, невозможно было разглядеть его Эмоция. Он опустил голову и тихо вздохнул."
  },
  AvgDialog_47169_Content_15 = {
    Text = "Лёгкий вздох прозвучал как гром в пустоте, Погоня за светом Начало разбегаться во все стороны."
  },
  AvgDialog_47169_Content_16 = {
    Text = "Мой господин? мой господин?.."
  },
  AvgDialog_47169_Content_17 = {
    Text = "Мой господин!!.."
  },
  AvgDialog_47169_Content_18 = {
    Text = "Свет слепил глаза Мириам, вызывая резь."
  },
  AvgDialog_47169_Content_19 = {
    Text = "В Кругозор, становящемся чётким, статуя стоит на подоконнике."
