  AvgDialog_49838_Content_78 = {
    Text = "Малышка покинула?"
  },
  AvgDialog_49838_Content_79 = {Text = "Нет."},
  AvgDialog_49838_Content_8 = {
    Text = "За спиной Нубии стоит Церковь света.\nСлова Давдейл не лишены смысла, похоже, необходимо любой ценой остановить ритуал."
  },
  AvgDialog_49838_Content_80 = {
    Text = "Малышка в тот момент осознала многое: оказалось, что запущенный сад не может вернуть себе былую чистоту, а невозможность издавать звуки... казалась невыносимо мучительной."
  },
  AvgDialog_49838_Content_81 = {
    Text = "Она самостоятельно прыгнула в Священную реку."
  },
  AvgDialog_49838_Content_82 = {
