  AvgDialog_49870_Content_14 = {
    Text = "Раны девушки Реи не слишком серьёзны, если бы помощь пришла немного позже, рана уже начала бы заживать."
  },
  AvgDialog_49870_Content_15 = {
    Text = "Но я так хочу.."
  },
  AvgDialog_49870_Content_16 = {
