  AvgDialog_49870_Content_22 = {
    Text = "...я хочу.."
  },
  AvgDialog_49870_Content_23 = {
    Text = "Рея резко поднялась, игла выскочила, Кровавые брызги из мешка и её кровь покрыли всё её тело."
  },
  AvgDialog_49870_Content_24 = {
