  AvgDialog_58291_Content_64 = {Text = "Бум!"},
  AvgDialog_58291_Content_65 = {
    Text = "Пуля точно прошла сквозь лицо таинственного человечка, оставив в центре огромную пустоту."
  },
  AvgDialog_58291_Content_66 = {
    Text = "Извините, пистолет случайно выстрелил. Интересная ли домашняя игра, N?"
