  AvgDialog_58292_Content_68 = {
    Text = "Лекк достал пистолет и неторопливо пошел вперед."
  },
  AvgDialog_58292_Content_69 = {
    Text = "Далее приглашаем выйти нашу убийцу, которая с момента преступления до сейчас ни разу не появлялась и могла только Паника прятаться в темноте."
