  AvgDialog_58293_Content_4 = {
    Text = "«Вы» сделали кивок."
  },
  AvgDialog_58293_Content_40 = {
    Text = "Попробуйте найти правду, уважаемые детективы."
  },
  AvgDialog_58293_Content_41 = {
    Text = "Как странно, разве максимальным подозреваемым не вы, дорогой господин N?"
  },
  AvgDialog_58293_Content_42 = {
    Text = "Кашель, кашель, позвольте уточнить — найдите преступника, который на самом деле мой двойник!"
