  AvgDialog_60888_Content_33 = {
    Text = "Верно, девятнадцать лет. Долгое время."
  },
  AvgDialog_60888_Content_34 = {
    Text = "Ассоциация скульпторов и Плаватель морей привлекли достаточно внимания, наши фигуры хорошо скрыты."
  },
  AvgDialog_60888_Content_35 = {
    Text = "План Ремуахе потерпел неудачу, жалко, но это неважно."
