  AvgDialog_60888_Content_39 = {
    Text = "Чтобы снова услышать музыку, подаренную тем великим существом, все жертвы кажутся незначительными."
  },
  AvgDialog_60888_Content_4 = {
    Text = "Дирижёрская палочка дирижёра прочертила в воздухе плавную дугу. Музыкальное произведение подошло к своей заключительной части."
  },
  AvgDialog_60888_Content_40 = {
    Text = "Повернувшись, он застыл. Молодой Дирижёр поднял руки, приветствуя пустой театр и таинственные глубины звёздного неба за его пределами."
