  AvgDialog_6773_Content_85 = {
    Text = "Другой «Шило» надменно смеялся, освободив все бушующие злые намерения в своём смехе."
  },
  AvgDialog_6773_Content_86 = {
    Text = "Хаха-хаха-хаха... Кто сказал, что мы с тобой один и тот же человек?"
