  AvgDialog_71793_Content_9 = {Text = "Я ——"},
  AvgDialog_71793_Content_90 = {
    Text = "То был наследник престола, наследники престола пробудили нашего господина!"
  },
  AvgDialog_71793_Content_91 = {
    Text = "С того момента, как увидел, что дети направляются к короне, главный жрец молча дал свое согласие и теперь глубоко поклонился Тулу, стоящему на самом верху алтаря — это был ритуальный знак полного подчинения священника королю."
  },
  AvgDialog_71793_Content_92 = {
