  AvgDialog_73781_Content_10 = {
    Text = "Очень хорошо, Клауд, ты можешь открыть глаза."
  },
  AvgDialog_73781_Content_11 = {
    Text = "В тихой, мягкой музыке проявляется незнакомая лечебная Комната, украшенная многочисленными инсектицидами."
  },
  AvgDialog_73781_Content_12 = {
    Text = "Клементина сидит напротив тебя, глядя на тебя с улыбкой.\nИли, скорее, на хозяина этой памяти."
  },
  AvgDialog_73781_Content_13 = {
    Text = "<LightGray:Клементина, почему снова ты?>"
