  AvgDialog_73781_Content_22 = {
    Text = "<LightGray:самость? Реальность я? неужели психотерапевты всегда говорят загадками…>"
  },
  AvgDialog_73781_Content_23 = {
    Text = "Клауд, похоже, тоже в замешательстве, раздумывая о глубоком значении «настоящего себя»."
