  AvgDialog_73783_Content_72 = {
    Text = "Ты поднимаешь голову и видишь, как Клементина улыбается тебе."
  },
  AvgDialog_73783_Content_73 = {
    Text = "Не надо позволять словам другого меня тебя смутить, %player%. В твоём сердце всегда есть правильный Лечение о твоей истинной сущности."
  },
  AvgDialog_73783_Content_74 = {
