  AvgDialog_73794_Content_16 = {Text = "Кто?"},
  AvgDialog_73794_Content_17 = {
    Text = "Выстрелы заменили Лечение отца, вместе с ними раздались крики, крики соплеменников."
  },
  AvgDialog_73794_Content_18 = {
