  AvgDialog_73794_Content_38 = {
    Text = "Однако не последовало ответа."
  },
  AvgDialog_73794_Content_39 = {
    Text = "Клементин!"
  },
  AvgDialog_73794_Content_4 = {
    Text = "…Остаточная воля, превращающаяся в светлячков?"
  },
  AvgDialog_73794_Content_40 = {
    Text = "Проверив дыхание, подтвердив слабое дыхание дочери, отец упал на колени от изнеможения."
  },
  AvgDialog_73794_Content_41 = {
    Text = "Звук колена, ударившегося о пол, разбудил Клементин."
  },
  AvgDialog_73794_Content_42 = {
    Text = "Отец... мне кажется, я слышал, что ты сказал, что собираешься покинуть это место?"
  },
  AvgDialog_73794_Content_43 = {
    Text = "Да, покинуть это место, вернуться… вернуться на родину."
