  AvgDialog_73794_Content_8 = {
    Text = "Почему... даже «я» не могу понять своего решения?"
  },
  AvgDialog_73794_Content_9 = {
    Text = "Ты уже не слышу, потому что те светящиеся бабочки устремились к тебе, окружили тебя, влились в тебя, словно кокон, окутав тебя."
  },
  AvgDialog_73795_Content_1 = {
    Text = "Бабочка летит"
  },
  AvgDialog_73795_Content_10 = {
    Text = "Тем не менее, ритуал более продвинут, чем теория, когда история @2 расы мелькает в твоем сознании, эти знания заставят тебя трансформироваться и возродиться, став моим сородичем как в теле, так и в понимании."
  },
  AvgDialog_73795_Content_11 = {
    Text = "Настоящий @2загадочный клан."
