  AvgDialog_73796_Content_14 = {
    Text = "Это... моя Комната!?"
  },
  AvgDialog_73796_Content_15 = {
    Text = "Ты встаёшь; хотя мозг всё ещё немного болит, и тело не выздоровело, но в этот миг тебе не до этого."
  },
  AvgDialog_73796_Content_16 = {
    Text = "Знакомая планировка и мебель, а также эта полная учебников парта… здесь действительно моя Комната."
  },
  AvgDialog_73796_Content_17 = {
    Text = "Не знаю, сколько раз я был здесь, торопливо догоняя те бесконечные задания."
