  AvgDialog_73796_Content_20 = {
    Text = "Но это действительно.."
  },
  AvgDialog_73796_Content_21 = {
    Text = "Человеческий мозг имеет множество недостатков, зрительный обман — один из них. Попробуйте присмотреться повнимательнее."
