  AvgDialog_73796_Content_4 = {
    Text = "Что, вам не нравится, что я появился в вашем сне?"
  },
  AvgDialog_73796_Content_40 = {
    Text = "Коммуникатор не подавал признаков жизни, а За дверью раздались пронзительные крики."
