  AvgDialog_73796_Content_41 = {
    Text = "За дверью кто-то есть!"
  },
  AvgDialog_73796_Content_42 = {
    Text = "Ты осторожно подкрался к двери и тихо приоткрыл её на щель."
  },
  AvgDialog_73796_Content_43 = {
    Text = "За дверью коридор знакомого санатория, несколько врачей в масках удерживают двух пациентов с кухонными ножами."
  },
  AvgDialog_73796_Content_44 = {
