  AvgDialog_78099_Content_4 = {
    Text = "Нет, я не благотворитель."
  },
  AvgDialog_78099_Content_5 = {
    Text = "Однако я не могу оставаться в стороне, когда тот, кто отнял у меня мою личность, мою лабораторию и моего щенка, пытается пропагандировать свои непрочные идеалы передо мной."
  },
  AvgDialog_78099_Content_6 = {
