  AvgDialog_78941_Content_21 = {
    Text = "Мой опыт подсказывает мне, да. Затем я рассчитаю приливы, чтобы определить лучшее место для высадки."
  },
  AvgDialog_78941_Content_22 = {
    Text = "Вы перестали говорить, создавая безопасную атмосферу для вычислений Куплощита, но вся палуба стала шумной."
  },
  AvgDialog_78941_Content_23 = {
    Text = "Корабль «Нордирис» перестал качаться, но все люди рядом вышли на палубу из-за недавнего тряски."
  },
  AvgDialog_78941_Content_24 = {
