  AvgDialog_78941_Content_54 = {Text = "...!!!"},
  AvgDialog_78941_Content_55 = {
    Text = "Из темноты внезапно протянулось щупальце, направляющееся к тебе, затем ты потерял сознание, упав на землю."
  },
  AvgDialog_78941_Content_56 = {
    Text = "Не переживай, я с тобой."
  },
  AvgDialog_78941_Content_57 = {
    Text = "Кабина на носу была разрушена морским чудовищем, нам необходимо двигаться к корме, к соединительному мосту, там есть штурвал."
  },
  AvgDialog_78941_Content_58 = {
    Text = "Керперт потянула вас к корме корабля, в то же время выжившие тоже стремились к корме."
  },
  AvgDialog_78941_Content_59 = {
    Text = "При проектировании Ноутилуса верфь оставила недостаточно спасательных шлюпок для максимизации прибыли."
  },
  AvgDialog_78941_Content_6 = {
    Text = "К моменту, когда в водонепроницаемое отделение поступит вода, энергетический отсек потухнет, и у Наутилуса будет только один Выход — затонуть на море."
  },
  AvgDialog_78941_Content_60 = {
    Text = "Сейчас нос корабля занимает морское чудовище, и спасательные шлюпки там больше не доступны, а десять с лишним спасательных лодок на корме вообще не могут вместить так много пассажиров."
  },
  AvgDialog_78941_Content_61 = {
    Text = "Вы опасаетесь, что пассажиры начнут драться за места в спасательных лодках?"
