    Text = "Не волнуйся, Носитель, хотя я её не знаю, Карен чувствует!"
  },
  AvgDialog_80279_Content_7 = {
    Text = "Карен расскажет хозяину, что она чувствует, будто попала на огромный банкет!"
  },
  AvgDialog_80279_Content_70 = {
    Text = "Она тоже одна из семьи Карен!"
  },
  AvgDialog_80279_Content_71 = {
    Text = "(связано с густым туманом и банкетом Карен при жизни…)"
  },
  AvgDialog_80279_Content_72 = {
    Text = "(вернусь и проведу расследование, неужели это…)"
  },
  AvgDialog_80279_Content_73 = {
    Text = "Ой! Времени не хватает!"
  },
  AvgDialog_80279_Content_74 = {
    Text = "Какое время?"
  },
  AvgDialog_80279_Content_75 = {
    Text = "Вечеринка, Носитель! Вечеринка, чтобы отпраздновать ваше становление мастером очищения!"
  },
  AvgDialog_80279_Content_76 = {
    Text = "Точно! Я тогда думал, что отличный повод собраться во время праздников."
  },
  AvgDialog_80279_Content_77 = {
    Text = "Что же делать, Карен! Ещё не поздно?"
  },
  AvgDialog_80279_Content_78 = {
    Text = "Не беспокойтесь, доверяйте Карен!"
  },
  AvgDialog_80279_Content_79 = {
    Text = "Что касается подготовки вечеринки, Карен тоже профессионал!"
  },
  AvgDialog_80279_Content_8 = {
    Text = "............"
  },
  AvgDialog_80279_Content_80 = {
    Text = "Носитель! Подготовка вечеринки должна ускориться! Вперед!"
  },
  AvgDialog_80279_Content_81 = {
    Text = "Слишком быстро, Карен! Подожди меня!"
