  AvgDialog_90539_Content_100 = {
    Text = "<Big:<Shake:Пусть лампа горит вечно! Пусть лампа горит вечно!>>"
  },
  AvgDialog_90539_Content_101 = {
    Text = "На резком крике Кастор поднял голову, смотря прямо в проницательный взгляд Юлиетты, излучая улыбку, которая никогда не поддавалась."
