  AvgDialog_90539_Content_41 = {
    Text = "Полиукс смотрел на слегка согнутую спину Кастора, слыша его все более мучительный вздох, никогда не ненавидел его упрямство так, как сейчас."
  },
  AvgDialog_90539_Content_42 = {
    Text = "(Хотя всё это он сам на себя навлек, почему я до сих пор так сбит с толку, так запутан?)"
