  AvgDialog_95476_Content_117 = {
    Text = "Это почти как следовать за посланником бога, совершая самоубийственные поступки, следуя святым и исполняя волю бога."
  },
  AvgDialog_95476_Content_118 = {
    Text = "Но все равно, лучше быть в компании, это более безопасно, не Правда ли?"
