  AvgDialog_98105_Content_40 = {
    Text = "Последняя полуфинальная игра — начинаем сейчас!"
  },
  AvgDialog_98105_Content_5 = {
    Text = "Когда Пандия громко кричит, ловкие клешни Расплавленной Куклы падают, завоевав первое очко."
  },
  AvgDialog_98105_Content_6 = {
    Text = "Сборище бездарностей! Если не хотите наказания, поднимите всех руки!"
  },
  AvgDialog_98105_Content_7 = {
    Text = "Хорошо, ваша величество! Без проблем, ваша величество! Но... можно мне предварительно наказать?"
