  AvgDialog_98107_Content_13 = {
    Text = "Эм, я хочу сказать..."
  },
  AvgDialog_98107_Content_14 = {
    Text = "Смотря на замешательство всех, вы не знаете, как начать - это сновидение слишком прекрасно, вам не хочется просыпаться."
  },
  AvgDialog_98107_Content_15 = {
    Text = "Может быть, %player%, ты хочешь навсегда сохранить воспоминание об этом моменте?"
