  AvgDialog_98284_Content_67 = {
    Text = "Это……эти……"
  },
  AvgDialog_98284_Content_68 = {
    Text = "Ты наблюдаешь за жидкостью, которая выбрасывается из твоего рта. Это кровь, не знаешь откуда, микробы и черви веселятся в ней."
  },
  AvgDialog_98284_Content_69 = {
    Text = "Твой желудок заурчал, и ты стал блевать на стол."
