  AvgDialog_98284_Content_85 = {
    Text = "Пикман безудержно говорит перед вами, вы совершенно не слышите, что он говорит."
  },
  AvgDialog_98284_Content_86 = {
    Text = "Ты не стройно повернулся, и следовал за ним, ступая бесчувственно вглубь этого странного города."
  },
  AvgDialog_98284_Content_9 = {
    Text = "Эй? Эвер?! Как ты нашел меня здесь?"
